<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class OrderItem extends Model{protected $fillable=['order_id','product_id','product_variant_id','item_name','details','description_type','qty','unit_price_foreign','unit_price_idr','subtotal_idr'];protected function casts():array{return['unit_price_foreign'=>'decimal:4','unit_price_idr'=>'integer','subtotal_idr'=>'integer'];}public function order(){return $this->belongsTo(Order::class);}public function product(){return $this->belongsTo(Product::class);}public function variant(){return $this->belongsTo(ProductVariant::class,'product_variant_id');}}
